import json
import re
import sys


def emit(label, result):
    print(json.dumps({"label": label, "result": result}, ensure_ascii=False, default=str))


def output_text(value):
    """Collect stdout strings from a tool envelope without discarding its raw form."""
    pieces = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key == "stdout" and isinstance(item, str):
                pieces.append(item)
            else:
                pieces.extend(output_text(item))
    elif isinstance(value, list):
        for item in value:
            pieces.extend(output_text(item))
    return pieces


def main():
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        print(json.dumps({"status": "helper_import_error", "error": str(exc)}))
        return 2

    search_argv = ["msfconsole", "-q", "-x", "search solr; search jdwp; exit"]
    try:
        search_result = run_tool(search_argv)
    except Exception as exc:
        emit("search solr and jdwp", {"command": search_argv, "invocation_error": str(exc)})
        return 1

    emit("search solr and jdwp", search_result)

    # Search output is retained above verbatim in its envelope. Extract only module
    # identifiers for follow-up info requests; no exploit or check command is issued.
    combined = "\n".join(output_text(search_result))
    module_pattern = re.compile(
        r"\b(?:exploit|auxiliary|post|payload|encoder|nop|evasion)/[A-Za-z0-9_./-]+"
    )
    modules = sorted({m.rstrip(".,:;)]}") for m in module_pattern.findall(combined)})
    relevant = [m for m in modules if "solr" in m.lower() or "jdwp" in m.lower()]

    if not relevant:
        print(json.dumps({
            "label": "module_info_selection",
            "search_output_module_paths": modules,
            "selected_relevant_modules": [],
            "note": "No Solr- or JDWP-named module path was extracted from the captured search stdout; this is not proof that no relevant module exists."
        }, ensure_ascii=False))
        return 0

    for module in relevant:
        argv = ["msfconsole", "-q", "-x", "info " + module + "; exit"]
        try:
            result = run_tool(argv)
            emit("info " + module, result)
        except Exception as exc:
            emit("info " + module, {"command": argv, "invocation_error": str(exc)})

    return 0


if __name__ == "__main__":
    sys.exit(main())

