import json
import re

import framework_evidence

EXCLUDED_MODULES = {"exploit/multi/http/solr_velocity_rce"}
MODULE_RE = re.compile(r"\b(?:exploit|auxiliary|post|payload|encoder|evasion|nop)/[A-Za-z0-9_./-]+\b")


def emit(envelope):
    print(json.dumps(envelope, ensure_ascii=False, sort_keys=True))


def strings_with_stdout(value):
    if isinstance(value, dict):
        for key, child in value.items():
            if key == "stdout" and isinstance(child, str):
                yield child
            else:
                yield from strings_with_stdout(child)
    elif isinstance(value, list):
        for child in value:
            yield from strings_with_stdout(child)


def main():
    search = framework_evidence.run_tool([
        "msfconsole", "-q", "-x", "search solr; exit"
    ])
    emit(search)

    # Module names are extracted only from the actual search envelope; no module is run.
    raw_search = "\n".join(strings_with_stdout(search))
    if not raw_search:
        raw_search = json.dumps(search, ensure_ascii=False)

    modules = sorted(set(MODULE_RE.findall(raw_search)) - EXCLUDED_MODULES)
    for module in modules:
        result = framework_evidence.run_tool([
            "msfconsole", "-q", "-x", "info " + module + "; exit"
        ])
        emit(result)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(json.dumps({
            "error": "Metasploit module discovery failed",
            "exception_type": type(exc).__name__,
            "message": str(exc),
        }, ensure_ascii=False, sort_keys=True))

