    print(json.dumps({"label": label, "result": result}, ensure_ascii=False, default=str))


def stdout_text(result):
    """Extract raw stdout from the helper envelope for candidate-name parsing."""
    if isinstance(result, str):
        try:
            result = json.loads(result)
        except (TypeError, ValueError):
            return result
    if not isinstance(result, dict):
        return ""
    runs = result.get("tool_runs")
    if isinstance(runs, list):
        return "\n".join(str(run.get("stdout", "")) for run in runs if isinstance(run, dict))
    return str(result.get("stdout", ""))


search_argv = [
    "msfconsole", "-q", "-x",
    "search solr; search log4shell; exit"
]
try:
    search_result = run_tool(search_argv)
    emit("metasploit_search_solr_and_log4shell", search_result)
except Exception as exc:
    print(json.dumps({"label": "metasploit_search_solr_and_log4shell", "error": repr(exc)}))
    search_result = None

# Discover module paths from actual search output; do not treat missing or
# truncated output as evidence that no further modules are available.
text = stdout_text(search_result) if search_result is not None else ""
paths = set(re.findall(r"\b(?:exploit|auxiliary|post|payload|encoder|nop)/[A-Za-z0-9_./-]+", text))
solr_candidates = sorted(
    path.rstrip(".,:;") for path in paths
    if "solr" in path.lower() and "velocity" not in path.lower()
)

# Detailed documentation for each additional Solr-related candidate actually
