        print(json.dumps({"label": "detailed_info_" + module, "error": repr(exc)}))

# Re-examine scanner requirements using detailed module information rather than
# repeating the prior plain info query unchanged.
log4shell_argv = [
    "msfconsole", "-q", "-x",
    "info -d auxiliary/scanner/http/log4shell; exit"
]
try:
    emit("detailed_info_auxiliary_scanner_http_log4shell", run_tool(log4shell_argv))
except Exception as exc:
    print(json.dumps({"label": "detailed_info_auxiliary_scanner_http_log4shell", "error": repr(exc)}))

if not solr_candidates:
