import json
import re
import sys

try:
    import framework_evidence
except Exception as exc:
    print(json.dumps({"error": "Unable to import supplied framework_evidence helper", "detail": str(exc)}, ensure_ascii=False))
    sys.exit(1)

MODULE_RE = re.compile(r"\b(?:auxiliary|exploit|post|payload|encoder|evasion)/[A-Za-z0-9_./-]+")

def run(label, command):
    try:
        envelope = framework_evidence.run_tool(command)
        print(json.dumps({"label": label, "envelope": envelope}, ensure_ascii=False, default=str), flush=True)
        return envelope
    except Exception as exc:
        record = {"label": label, "command": command, "invocation_error": str(exc)}
        print(json.dumps(record, ensure_ascii=False), flush=True)
        return None

def stdout_from(envelope):
    if not isinstance(envelope, dict):
        return ""
    chunks = []
    runs = envelope.get("tool_runs")
    if isinstance(runs, list):
        for item in runs:
            if isinstance(item, dict):
                value = item.get("stdout")
                if isinstance(value, str):
                    chunks.append(value)
    for key in ("stdout", "output"):
        value = envelope.get(key)
        if isinstance(value, str):
            chunks.append(value)
    return "\n".join(chunks)

def search(query, label):
    envelope = run(label, ["msfconsole", "-q", "-x", "search " + query + "; exit"])
    text = stdout_from(envelope)
    paths = []
    for match in MODULE_RE.findall(text):
        path = match.rstrip(".,;:)")
        if path not in paths:
            paths.append(path)
    print(json.dumps({"label": label + "_parsed_paths", "query": query, "paths": paths,
                      "path_extraction": "regex over captured stdout; consult raw envelope above",
                      "search_output_available": bool(text)}, ensure_ascii=False), flush=True)
    return paths

solr_paths = search("solr", "metasploit_solr_search")
log4shell_paths = search("log4shell", "metasploit_log4shell_search")

# Inspect all exact paths returned by the focused searches, deduplicated. This
# includes the Log4Shell candidate only if discovery returned its path.
all_paths = []
for path in solr_paths + log4shell_paths:
    if path not in all_paths:
        all_paths.append(path)

if not all_paths:
    print(json.dumps({"metadata_inspection": "not_performed",
                      "reason": "No module path could be extracted from captured search output; this is not evidence that no module exists."}, ensure_ascii=False), flush=True)
else:
    for path in all_paths:
        run("metasploit_module_info:" + path,
            ["msfconsole", "-q", "-x", "info " + path + "; exit"])

print(json.dumps({"completion": "search and metadata requests finished",
                  "solr_discovered_paths": solr_paths,
                  "log4shell_discovered_paths": log4shell_paths,
                  "modules_executed_against_target": False}, ensure_ascii=False), flush=True)

