from framework_evidence import run_tool


def stdout_strings(value):
    """Collect stdout strings without discarding the original tool envelope."""
    found = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key == "stdout" and isinstance(item, str):
                found.append(item)
            else:
                found.extend(stdout_strings(item))
    elif isinstance(value, list):
        for item in value:
            found.extend(stdout_strings(item))
    return found


def relevant_trend_modules(envelope):
    modules = []
    # Metasploit search rows begin with an index and a module path. Only retain
    # rows whose actual displayed text indicates a Trend Micro-related result.
    row = re.compile(r"^\s*\d+\s+((?:auxiliary|exploit|post|payload|encoder|nop)/[A-Za-z0-9_./-]+)\s+.*$", re.I)
    for text in stdout_strings(envelope):
        for line in text.splitlines():
            match = row.match(line)
            if match and re.search(r"trend\s*micro|trendmicro|officescan|deep\s*security", line, re.I):
                module = match.group(1)
                if module not in modules:
                    modules.append(module)
    return modules


