        records.append({"candidate": "Trend Micro", "identifier": module,
                        "operation": "info", "envelope": result})
    except Exception as exc:
        records.append({"candidate": "Trend Micro", "identifier": module,
                        "operation": "info", "execution_error": repr(exc)})

summary = {
    "Log4Shell scanner": {
        "identifier": log4shell_id,
        "info_requested": True,
        "request_recorded": any(r.get("candidate") == "Log4Shell scanner" for r in records),
    },
    "Trend Micro": {
        "identifiers_established_by_focused_search": trend_ids,
        "info_requested_for": trend_ids,
        "identifier_not_established": not bool(trend_ids),
        "qualification": "This reports only what the focused search and available discovery evidence establish; it is not proof that no such Metasploit module exists." if not trend_ids else "",
    },
}
print(json.dumps({"purpose": "Metasploit module information and candidate identifier follow-up",
                  "summary": summary, "records": records}, ensure_ascii=False))

