import re

import framework_evidence


def get_stdout(value):
    """Collect stdout strings from the helper envelope without discarding it."""
    found = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key == "stdout" and isinstance(item, str):
                found.append(item)
            else:
                found.extend(get_stdout(item))
    elif isinstance(value, list):
        for item in value:
            found.extend(get_stdout(item))
    return found


def trendmicro_module_paths(envelope):
    paths = set()
    module_re = re.compile(
        r"^\s*\d+\s+((?:auxiliary|exploit|post|payload|encoder|nop|evasion|" 
        r"analyzer|login|gather|fileformat|chaining|capture)/\S+)",
        re.IGNORECASE,
    )
    for text in get_stdout(envelope):
        in_results = False
        for line in text.splitlines():
            if "Matching Modules" in line:
                in_results = True
                continue
            if in_results:
                match = module_re.match(line)
                if match:
                    paths.add(match.group(1).rstrip(".,;"))
                # Metasploit's result table ends at its first blank line after rows.
                elif not line.strip() and paths:
                    in_results = False
    return sorted(paths)


runs = []
errors = []
scanner_path = "auxiliary/scanner/http/log4shell_scanner"
