import json
import re

from framework_evidence import run_tool


def emit(label, result):
    print(json.dumps({"operation": label, "evidence": result}, ensure_ascii=False, default=str))


def get_stdout(value):
    if isinstance(value, dict):
        direct = value.get("stdout")
        if isinstance(direct, str):
            return direct
        for child in value.values():
            found = get_stdout(child)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = get_stdout(child)
            if found:
                return found
    elif isinstance(value, str):
        try:
            return get_stdout(json.loads(value))
        except (json.JSONDecodeError, TypeError):
            return ""
    return ""


def run(label, command):
    try:
        result = run_tool(command)
    except Exception as exc:
        result = {"status": "wrapper_exception", "error": repr(exc), "command": command}
    emit(label, result)
    return result


# Inspect the exact scanner module path identified by the discovery evidence.
run(
    "info auxiliary/scanner/http/log4shell_scanner",
    ["msfconsole", "-q", "-x", "info auxiliary/scanner/http/log4shell_scanner; exit -y"],
)

# Search focused Trend Micro terms because the prior discovery capture was partial.
seen = set()
for query in ("trendmicro", "\"Trend Micro\""):
    result = run(
        "search " + query,
        ["msfconsole", "-q", "-x", "search " + query + "; exit -y"],
    )
    output = get_stdout(result)
    for line in output.splitlines():
        match = re.match(r"^\s*\d+\s+((?:auxiliary|exploit|post|payload|encoder|nop|evasion)/\S+)", line)
        if not match:
            continue
        path = match.group(1).rstrip(".,;")
        if path in seen:
            continue
        # Only inspect paths whose actual result row identifies the Trend Micro search term.
        if "trend" not in line.lower() and "micro" not in line.lower():
            continue
        seen.add(path)
        run(
            "info " + path,
            ["msfconsole", "-q", "-x", "info " + path + "; exit -y"],
        )

if not seen:
    print(json.dumps({
        "operation": "Trend Micro candidate coverage",
        "observation": "No module path was parsed from the captured Trend Micro search output; this does not establish that no relevant module exists.",
    }))

