import json
import re
from framework_evidence import run_tool

MODULE_RE = re.compile(r"(?:auxiliary|exploit|post|payload|encoder|nop)/[A-Za-z0-9_./-]+")


def emit(label, result):
    print(json.dumps({"label": label, "evidence": result}, ensure_ascii=False, default=str))


def stdout_text(value):
    """Get captured stdout without discarding the original envelope."""
    if isinstance(value, dict):
        if isinstance(value.get("stdout"), str):
            return value["stdout"]
        for item in value.values():
            text = stdout_text(item)
            if text:
                return text
    elif isinstance(value, list):
        for item in value:
            text = stdout_text(item)
            if text:
                return text
    elif isinstance(value, str):
        # The helper may return a serialized envelope.
        try:
            decoded = json.loads(value)
        except (TypeError, ValueError):
            return value
        if decoded != value:
            return stdout_text(decoded)
    return ""


def trend_candidate_paths(search_output):
    paths = set()
    for line in search_output.splitlines():
        if re.search(r"trend\s*micro|trendmicro", line, re.IGNORECASE):
            for path in MODULE_RE.findall(line):
                paths.add(path.rstrip(".,;"))
    return sorted(paths)


# Inspect the exact path found by focused discovery.
log4shell = run_tool([
    "msfconsole", "-q", "-x",
    "info auxiliary/scanner/http/log4shell_scanner; exit -y"
])
emit("info auxiliary/scanner/http/log4shell_scanner", log4shell)

# Search separately for Trend Micro candidates, retaining the full search output.
trend_search = run_tool([
    "msfconsole", "-q", "-x", "search type:auxiliary trendmicro; exit -y"
])
emit("search type:auxiliary trendmicro", trend_search)

search_output = stdout_text(trend_search)
candidates = trend_candidate_paths(search_output)
print(json.dumps({
    "label": "candidate_paths_extracted_from_trend_search_rows",
    "paths": candidates,
    "extraction_method": "module path on a search-output line containing Trend Micro or TrendMicro"
}, ensure_ascii=False))

for path in candidates:
    result = run_tool([
        "msfconsole", "-q", "-x", "info " + path + "; exit -y"
    ])
    emit("info " + path, result)

