import base64
import json
import urllib.error
import urllib.request

URL = "http://192.168.5.7:8983/solr/admin/info/system?wt=json"
TIMEOUT_SECONDS = 30


class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def read_body(response):
    chunks = []
    read_error = None
    while True:
        try:
            chunk = response.read(65536)
        except Exception as exc:
            read_error = {"type": type(exc).__name__, "message": str(exc)}
            break
        if not chunk:
            break
        chunks.append(chunk)
    body = b"".join(chunks)
    return body, read_error


request = urllib.request.Request(
    URL,
    method="GET",
    headers={"Accept": "application/json, */*", "User-Agent": "Solr-system-info-evidence/1.0"},
)
opener = urllib.request.build_opener(NoRedirectHandler())
result = {
    "method": "GET",
    "requested_url": URL,
    "timeout_seconds": TIMEOUT_SECONDS,
}

try:
    response = opener.open(request, timeout=TIMEOUT_SECONDS)
except urllib.error.HTTPError as exc:
    response = exc
except Exception as exc:
    result.update({
        "outcome": "transport_or_request_error",
        "error": {"type": type(exc).__name__, "message": str(exc)},
        "http_response_received": False,
        "body_complete": False,
    })
else:
    result["outcome"] = "http_response"
    result["http_response_received"] = True

if "response" in locals():
    result["outcome"] = "http_response"
    result["http_response_received"] = True
    result["status"] = getattr(response, "code", None)
    result["reason"] = getattr(response, "reason", None)
    result["response_headers"] = list(response.headers.items()) if response.headers else []
    body, read_error = read_body(response)
    result["body_base64"] = base64.b64encode(body).decode("ascii")
    result["body_text_utf8_replacement"] = body.decode("utf-8", errors="replace")
    result["body_bytes_read"] = len(body)
    result["body_complete"] = read_error is None
    if read_error is not None:
        result["body_read_error"] = read_error
    try:
        response.close()
    except Exception:
        pass

print(json.dumps(result, ensure_ascii=False))
